  public MainForm(){Text="MGU Recorder — установка через ENET";ClientSize=new Size(820,720);MinimumSize=SizeFromClientSize(ClientSize);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(14,24,37);ForeColor=Color.FromArgb(235,241,247);AutoScaleMode=AutoScaleMode.Dpi;
