   LabelAt("SSH-ключ",28,220,95);Box(key,128,215,548);ButtonAt(browse,"Выбрать",686,213,105,32);browse.Click+=(s,e)=>{using(var d=new OpenFileDialog{Title="Ключ SSH владельца",Filter="Файлы ключей|*.*",CheckFileExists=true})if(d.ShowDialog(this)==DialogResult.OK)key.Text=d.FileName;};
