   ButtonAt(check,"Проверить",28,347,122,40);ButtonAt(install,"Установить",158,347,122,40);ButtonAt(uninstall,"Удалить",288,347,122,40);ButtonAt(result,"Открыть RESULT",418,347,155,40);ButtonAt(rollback,"Откат",581,347,90,40);ButtonAt(restart,"Перезапуск",679,347,112,40);uninstall.BackColor=Color.FromArgb(75,35,42);uninstall.FlatAppearance.BorderColor=Color.FromArgb(157,80,89);install.Enabled=false;uninstall.Enabled=false;rollback.Enabled=false;restart.Enabled=false;result.Enabled=false;
