   donation.Controls.Add(new Label{Name="donationCard",Text="2202 2073 7001 1432",Dock=DockStyle.Bottom,Height=30,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=Color.FromArgb(74,222,128)});
