   var ssh=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".ssh");foreach(var name in new[]{"id_ed25519","id_rsa"})if(File.Exists(Path.Combine(ssh,name))){key.Text=Path.Combine(ssh,name);break;}
   try{Directory.CreateDirectory(settingsDir);var file=Path.Combine(settingsDir,"active-run.json");if(File.Exists(file)){active=Data.Parse(File.ReadAllText(file));host.Text=Data.Text(active,"host");port.Text=Data.Text(active,"port","22");lastRun=Data.Text(active,"transaction",null);Log("Сохранённая установка: нажмите «Проверить» для чтения результата.");}}catch{}
