  void LabelAt(string text,int x,int y,int w){Controls.Add(new Label{Text=text,Location=new Point(x,y),Size=new Size(w,25)});}
  void Box(TextBox b,int x,int y,int w){b.Location=new Point(x,y);b.Size=new Size(w,30);b.BackColor=Color.FromArgb(27,43,61);b.ForeColor=ForeColor;b.BorderStyle=BorderStyle.FixedSingle;Controls.Add(b);}
  void ButtonAt(Button b,string text,int x,int y,int w,int h){b.Text=text;b.Location=new Point(x,y);b.Size=new Size(w,h);b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(68,105,137);b.BackColor=Color.FromArgb(28,54,78);b.ForeColor=ForeColor;Controls.Add(b);}
  void OnUi(Action a){if(IsDisposed)return;if(InvokeRequired){try{BeginInvoke(a);}catch{}}else a();}
  void Log(string s){OnUi(()=>logBox.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+s+Environment.NewLine));if(lastLog!=null)lastLog.Add(s);}
  void Progress(ProgressInfo p){OnUi(()=>{bar.Value=Math.Max(0,Math.Min(100,p.Percent));status.Text=p.Message;});}
  void Busy(bool on){working=on;foreach(var c in new Control[]{host,user,port,key,secret,browse,check,install,uninstall,rollback,restart})c.Enabled=!on;install.Enabled=!on&&Data.Flag(lastCheck,"supported");uninstall.Enabled=!on&&Workflow.CanUninstall(lastCheck);rollback.Enabled=!on&&lastCheck!=null&&selected!=null&&!String.IsNullOrEmpty(lastRun)&&active!=null&&Data.Text(active,"host")==selected.Host&&Data.Text(active,"operation","install")=="install";restart.Enabled=!on&&lastCheck!=null&&(Data.Flag(lastCheck,"supported")||Data.Flag(lastCheck,"removalSupported"));result.Enabled=lastLog!=null;}
  Credentials Cred(){return new Credentials{User=user.Text.Trim(),KeyFile=key.Text.Trim(),Secret=secret.Text};}
  Target ChooseTarget(string address,int sshPort){if(String.IsNullOrWhiteSpace(address)){var t=Enet.Discover(Log,CancellationToken.None);t.Port=sshPort;return t;}System.Net.IPAddress parsed;if(!System.Net.IPAddress.TryParse(address,out parsed)||parsed.AddressFamily!=System.Net.Sockets.AddressFamily.InterNetwork)throw new InvalidOperationException("Укажите IPv4-адрес MGU или оставьте поле пустым.");var ifs=Enet.Interfaces();string local=null;if(parsed.ToString().StartsWith("169.254.",StringComparison.Ordinal)){if(ifs.Count==1)local=ifs[0].Local;else if(selected!=null&&ifs.Any(i=>i.Local==selected.Local))local=selected.Local;else if(ifs.Count>1)throw new InvalidOperationException("Несколько ENET-адресов. Оставьте IP пустым для поиска нужного адаптера.");}return new Target{Host=parsed.ToString(),Port=sshPort,Local=local,Adapter="ручной адрес"};}
  bool Trust(Target target,string fp){bool accepted=false;Invoke((Action)(()=>{var knownFile=Path.Combine(settingsDir,"known-hosts.json");Dictionary<string,object> known;try{known=Data.Parse(File.ReadAllText(knownFile));}catch{known=new Dictionary<string,object>();}string previous=Data.Text(known,target.Label,null);if(previous==fp){accepted=true;return;}string text=(previous==null?"Новый ключ SSH автомобиля.":"Ключ SSH автомобиля изменился.")+Environment.NewLine+Environment.NewLine+target.Label+Environment.NewLine+fp+Environment.NewLine+Environment.NewLine+"Доверять этому ключу для подключённого автомобиля?";accepted=MessageBox.Show(this,text,"Ключ автомобиля",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)==DialogResult.Yes;if(accepted){known[target.Label]=fp;File.WriteAllText(knownFile,Data.Stringify(known));}}));return accepted;}
  void SaveActive(Target t,string run,string operation){active=new Dictionary<string,object>{{"host",t.Host},{"port",t.Port},{"transaction",run},{"operation",operation},{"created",DateTime.UtcNow.ToString("o")}};File.WriteAllText(Path.Combine(settingsDir,"active-run.json"),Data.Stringify(active));}
  async Task Run(string operation){if(working)return;bool doInstall=operation=="install",doUninstall=operation=="uninstall";if(doUninstall){if(!Workflow.CanUninstall(lastCheck))return;if(MessageBox.Show(this,"Удалить приложение Recorder и сервер регистратора?\n\nЗаписи и настройки архива сохранятся. Общие компоненты mgu-store останутся.\n\nШлюз видео этого сервера для задних экранов будет удалён.","Удаление регистратора",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;}int sshPort;if(!Int32.TryParse(port.Text,out sshPort)||sshPort<1||sshPort>65535){MessageBox.Show(this,"Неверный порт SSH.");return;}var cred=Cred();if(!String.IsNullOrEmpty(cred.KeyFile)&&!File.Exists(cred.KeyFile)){MessageBox.Show(this,"Файл SSH-ключа не найден.");return;}string address=host.Text.Trim();lastLog=new RunLog(cred.Secret,cred.KeyFile);lastLog.Result["status"]="CHECKING";lastLog.Result["operation"]=operation;lastLog.Result["sshAccessible"]=false;lastLog.Result["authorized"]=false;lastLog.Result["storeInstalled"]=null;Busy(true);bar.Value=0;
   try{await Task.Run(()=>{
    Payload.Verify(Log);selected=ChooseTarget(address,sshPort);OnUi(()=>enetLabel.Text="ENET: "+selected.Host);lastLog.Result["host"]=selected.Host;lastLog.Result["sourceAddress"]=selected.Local;
    if(!Enet.Banner(selected))throw new InvalidOperationException("SSH недоступен. MGU Store сам по себе не гарантирует включённый SSH. Установщик не выполняет SSH-разблокировку.");lastLog.Result["sshAccessible"]=true;OnUi(()=>sshLabel.Text="SSH: доступен");Log("SSH отвечает. Проверка авторизации…");
    using(var remote=new Remote(selected,cred,fp=>Trust(selected,fp))){lastLog.Result["authorized"]=true;lastLog.Result["hostFingerprint"]=remote.Fingerprint;OnUi(()=>sshLabel.Text="SSH: авторизован");var workflow=new Workflow(Log,Progress,(run,op)=>{lastRun=run;SaveActive(selected,run,op);});lastCheck=workflow.Check(remote);lastLog.Result["preflight"]=lastCheck;lastLog.Result["storeInstalled"]=Data.Flag(lastCheck,"storeInstalled");OnUi(()=>storeLabel.Text=Data.Flag(lastCheck,"storeInstalled")?"Store: "+Data.Text(lastCheck,"storeVersion"):"Store: не найден");
     if(active!=null&&Data.Text(active,"host")==selected.Host&&!String.IsNullOrEmpty(Data.Text(active,"transaction",null))){lastRun=Data.Text(active,"transaction");var job=workflow.Poll(remote,lastRun);if(new[]{"RUNNING","STARTING"}.Contains(Data.Text(job,"status"))){Log("Читается результат уже запущенной операции…");lastLog.Result["transaction"]=lastRun;var finished=workflow.Monitor(remote,lastRun,lastLog,t=>OnUi(()=>status.Text="Операция на MGU продолжается…"));Summarize(finished);lastCheck=workflow.Check(remote);return;}else{lastLog.Result["previousJob"]=job;Log("Результат сохранённой операции: "+Data.Text(job,"status"));}}
     if(!doInstall&&!doUninstall){if(!Data.Flag(lastCheck,"supported")){Workflow.RequireRemovalSupport(lastCheck);Log("Установка сейчас недоступна. Можно удалить установленный регистратор.");}else{foreach(var a in workflow.Plan(lastCheck))Log("Будет установлен: "+Workflow.ComponentLabel(Data.Text(a,"id"))+" "+Data.Text(a,"version"));Log("Проверка пройдена.");}if(Workflow.CanUninstall(lastCheck))Log("Доступно удаление приложения Recorder и сервера регистратора.");lastLog.Result["status"]="CHECK_PASSED";Progress(new ProgressInfo{Percent=100,Message=Data.Flag(lastCheck,"supported")?"Проверка завершена. Выберите действие.":"Доступно удаление регистратора."});return;}
     if(doUninstall)Workflow.RequireRemovalSupport(lastCheck);else Workflow.RequireSupport(lastCheck);
     lastRun=doUninstall?workflow.Uninstall(remote,lastCheck,lastLog):workflow.Install(remote,lastCheck,lastLog);if(lastRun!=null){SaveActive(selected,lastRun,operation);var finished=workflow.Monitor(remote,lastRun,lastLog,t=>OnUi(()=>status.Text=doUninstall?"Удаление через mgu-deploy…":"Установка через MGU Store…"));Summarize(finished);lastCheck=workflow.Check(remote);}else Progress(new ProgressInfo{Percent=100,Message=doUninstall?"Регистратор уже удалён.":"Установлены актуальные компоненты."});
    }
   });}
   catch(SshAuthenticationException){lastLog.Result["status"]="AUTHORIZATION_REQUIRED";Log("Авторизация не пройдена. Укажите ключ владельца, его фразу или корректный пароль SSH. Новых действий на MGU не выполнено.");status.Text="SSH доступен, авторизация не пройдена.";lastCheck=null;}
   catch(Exception e){bool running=active!=null&&Data.Text(active,"transaction",null)==lastRun;lastLog.Result["status"]=running?"CONNECTION_LOST_CHECK_RESULT":"STOPPED";lastLog.Result["error"]=lastLog.Redact(e.Message);Log(e.Message);status.Text=running?"Операция на MGU может продолжаться. Нажмите «Проверить».":"Остановлено. Подробности в RESULT.";lastCheck=null;}
   finally{lastLog.Save();if(doInstall||doUninstall)secret.Text="";Busy(false);}
  }
  void Summarize(Dictionary<string,object> job){if(Data.Text(job,"status")=="FINISHED"){Log(Data.Text(job,"operation")=="uninstall"?"Приложение Recorder и сервер регистратора удалены. Записи, настройки архива и общие компоненты mgu-store сохранены.":"Регистратор установлен. Архив, настройки и сопряжение RSE сохранены.");Log("Если Store запрашивает перезапуск, нажмите «Перезапуск».");}else Log("Операция не завершена: "+Data.Text(job,"status")+". Состояние и журнал сохранены в RESULT.");}
  async Task Extra(bool reboot){if(working||selected==null)return;if(MessageBox.Show(this,reboot?"Выполнить штатный перезапуск MGU?":"Откатить приложение Recorder и сервер регистратора? Общие компоненты mgu-store останутся.",reboot?"Перезапуск":"Откат",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;var cred=Cred();Busy(true);try{await Task.Run(()=>{using(var remote=new Remote(selected,cred,fp=>Trust(selected,fp))){var w=new Workflow(Log,Progress);if(reboot)w.Restart(remote);else w.Rollback(remote,lastRun,lastLog);}});}catch(Exception e){Log(e.Message);}finally{if(lastLog!=null)lastLog.Save();Busy(false);}}
  public void Render(string file){StartPosition=FormStartPosition.Manual;Location=new Point(-32000,-32000);CreateControl();Show();Application.DoEvents();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(file,System.Drawing.Imaging.ImageFormat.Png);}Close();}
